```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?government ?importIndustry ?exportIndustry ?religion
WHERE {
  FILTER (!isLiteral(?government) || lang(?government) = '' || langMatches(lang(?government), 'en'))
  FILTER (!isLiteral(?importIndustry) || lang(?importIndustry) = '' || langMatches(lang(?importIndustry), 'en'))
  FILTER (!isLiteral(?exportIndustry) || lang(?exportIndustry) = '' || langMatches(lang(?exportIndustry), 'en'))
  FILTER (!isLiteral(?religion) || lang(?religion) = '' || langMatches(lang(?religion), 'en'))

  # Find the country with Badakhshan Province
  ?country ns:location.country.administrative_divisions ns:m.04pwfx .

  # Type of government
  OPTIONAL { ?country ns:location.country.form_of_government ?government . }

  # Primary imports
  OPTIONAL {
    ?country ns:location.statistical_region.major_imports ?majorImport .
    ?majorImport ns:location.imports_exports_by_industry.industry ?importIndustry .
  }

  # Primary exports
  OPTIONAL {
    ?country ns:location.statistical_region.major_exports ?majorExport .
    ?majorExport ns:location.imports_exports_by_industry.industry ?exportIndustry .
  }

  # Religions practiced (for Tsakhur language countries)
  {
    # Also find the country that uses Tsakhur language and get religions
    ?country2 ns:location.country.languages_spoken ns:m.027bj_4 .
    ?country2 ns:location.statistical_region.religions ?rel .
    ?rel ns:location.religion_percentage.religion ?religion .
    FILTER (?country = ?country2)
  } UNION {
    # If not same country or no info, keep religion empty
    BIND("" AS ?religion)
  }
}
```

