      WHERE {
        ?team ns:sports.sports_team.championships ?championshipInner .
        ?championshipInner ns:time.event.start_date ?dateInner .
        BIND(xsd:dateTime(?dateInner) AS ?dtInner)
      }
      GROUP BY ?team
    }
    FILTER(?dt = ?minDate)
    BIND(?minDate AS ?result)
  }
  UNION
  {
    # Arena or practice location
    ?team ns:sports.sports_team.arena_stadium ?arena .
    BIND(?arena AS ?result)
  }
}
LIMIT 100
