SELECT DISTINCT ?x
WHERE {
  ns:m.081pw ns:time.event.start_date ?start ;
             ns:time.event.end_date ?end .
  ?x ns:government.politician.government_positions_held ?y .
  ?y ns:government.government_position_held.office_position_or_title ns:m.060d2 ; # President of the United States
     ns:government.government_position_held.from ?from ;
     ns:government.government_position_held.to ?to .
  FILTER (?from < ?end)
  FILTER (?to > ?start)

  # First question condition: started before 1939-01-02
  {
    FILTER (?from < "1939-01-02"^^xsd:dateTime)
  }
  UNION
  # Second question condition: held position until exactly 1933-12-31
  {
    FILTER (?to = "1933-12-31"^^xsd:dateTime)
  }
  UNION
  # Third question condition: terminated position after 1940-01-18
  {
    FILTER (?to > "1940-01-18"^^xsd:dateTime)
  }
}
