PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?x
WHERE {
  ns:m.081pw ns:time.event.start_date ?wwii_start ;
             ns:time.event.end_date ?wwii_end .

  ?x ns:government.politician.government_positions_held ?pos1 .
  ?pos1 ns:government.government_position_held.office_position_or_title ns:m.060d2 ;  # President of the United States
        ns:government.government_position_held.from ?from1 ;
        ns:government.government_position_held.to ?to1 .
  FILTER(?from1 < ?wwii_end && ?to1 > ?wwii_start)

  ?x ns:government.politician.government_positions_held ?pos2 .
  ?pos2 ns:government.government_position_held.office_position_or_title ns:m.0fj45 .  # Governor-General

  FILTER EXISTS {
    ?pos1 ns:government.government_position_held.appointed_by ns:m.083q7 . # appointed by Woodrow Wilson
  }
  FILTER(?from1 < "1939-01-02T00:00:00"^^xsd:dateTime)
}
```

```SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?result
WHERE {
  ?c ns:event.public_speaker.speeches_or_presentations ?speech .
  ?speech ns:event.speech_or_presentation.speech_topic ns:m.02mdg .
  {
    # Political offices other than current
    ?c ns:government.politician.government_positions_held ?pos .
    ?pos ns:government.government_position_held.office_position_or_title ?result .
    FILTER (?result != ?c)
    OPTIONAL { ?pos ns:government.government_position_held.to ?end }
    FILTER(BOUND(?end)) # Position ended (other than current)
  }
  UNION
  {
    # Party affiliation
    ?c ns:government.politician.party ?partyRole .
    ?partyRole ns:government.political_party_tenure.party ?result .
    FILTER (?result != ?c)
  }
}
