WHERE {
  ns:m.081pw ns:time.event.start_date ?start ;
             ns:time.event.end_date ?end .
  ?person ns:government.politician.government_positions_held ?pos .
  ?pos ns:government.government_position_held.office_position_or_title ns:m.060d2 ;  # President of the United States
       ns:government.government_position_held.from ?from ;
       ns:government.government_position_held.to ?to ;
       ns:government.government_position_held.jurisdiction_of_office ?country .
  FILTER (?from < ?end && ?to > ?start)
  {
    ?person ns:people.person.quotations ns:m.048c7zz .  # "I would rather have peace in the world than be President?"
  }
  UNION
  {
    ?person ns:people.person.quotations ns:m.048c8ml .  # "If you can't stand the heat, get out of the kitchen"
  }
}
```

```PREFIX ns: <http://rdf.freebase.com/ns/>
