WHERE {
  FILTER (?x != ns:m.0c8wxp)
  FILTER (!isLiteral(?x) || lang(?x) = '' || langMatches(lang(?x), 'en'))
  ns:m.0c8wxp ns:religion.religion.deities ?x .
  {
    # Quotation: "Repent: for the kingdom of heaven is at hand."
    ?x ns:people.person.quotations ns:m.094t_k_ .
