```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?hometown ?political_party ?disease
WHERE {
  FILTER (!isLiteral(?hometown) || lang(?hometown) = '' || langMatches(lang(?hometown), 'en'))
  FILTER (!isLiteral(?political_party) || lang(?political_party) = '' || langMatches(lang(?political_party), 'en'))
  FILTER (!isLiteral(?disease) || lang(?disease) = '' || langMatches(lang(?disease), 'en'))

  ?dedicatee ns:media_common.dedicatee.dedications ?dedication .
  ?dedication ns:media_common.dedication.dedicated_by ns:m.083pr .

  ?dedicatee ns:people.person.place_of_birth ?hometown .

  OPTIONAL {
    ?dedicatee ns:government.politician.party ?party .
    ?party ns:government.political_party_tenure.party ?political_party .
  }

  OPTIONAL {
    ?dedicatee ns:medicine.notable_person_with_medical_condition.condition ?disease .
  }
}
